alternativas:
SELECT f.nome
FROM funcionarios f, funcionarios g
WHERE f.salario > g.salario;

SELECT nome FROM funcionarios
GROUP BY nome
HAVING COUNT(*) > 1;

SELECT nome, COUNT(*) FROM funcionarios
WHERE COUNT(*) > 1
GROUP BY nome;

questoes.gabarito_sql:
SELECT nome, cargo, departamento_id, salario,
       RANK() OVER (PARTITION BY departamento_id ORDER BY salario DESC) AS posicao
FROM funcionarios;

SELECT nome, departamento_id, salario,
       ROUND(salario - AVG(salario) OVER (PARTITION BY departamento_id), 2) AS diferenca_da_media
FROM funcionarios;
